from __future__ import annotations

import datetime as dt
from types import SimpleNamespace
from typing import Any

import httpx2
import pytest
from ds.data.raw import copilot
from pydantic import SecretStr

TOKEN = "fake-token"  # noqa: S105  # not a real token: the transport is faked


def _snapshot(**changed: Any) -> dict[str, Any]:
    unlimited = {
        "entitlement": 0,
        "quota_remaining": 0.0,
        "percent_remaining": 100.0,
        "unlimited": True,
        "credits_used": 0,
        "overage_count": 0,
    }
    return unlimited | changed


ANSWER = {
    "copilot_plan": "individual_pro",
    "quota_reset_date": "2026-12-01",
    "token_based_billing": True,
    "quota_snapshots": {
        "chat": _snapshot(),
        "completions": _snapshot(),
        "premium_interactions": _snapshot(
            entitlement=7000, quota_remaining=6977.3, percent_remaining=99.6, unlimited=False, credits_used=22
        ),
    },
}


@pytest.fixture(autouse=True)
def stored_token(monkeypatch: pytest.MonkeyPatch) -> None:
    settings = SimpleNamespace(github_copilot_token=SecretStr(TOKEN))
    monkeypatch.setattr(copilot, "get_settings", lambda: settings)


def _client(status: int, body: Any, seen: list[httpx2.Request] | None = None) -> httpx2.Client:
    def handler(request: httpx2.Request) -> httpx2.Response:
        if seen is not None:
            seen.append(request)
        return httpx2.Response(status, json=body)

    return httpx2.Client(transport=httpx2.MockTransport(handler))


def test_the_premium_quota_the_plan_and_the_reset_day_are_read() -> None:
    seen: list[httpx2.Request] = []
    usage = copilot.copilot_usage(_client(200, ANSWER, seen))
    assert (usage.plan, usage.resets, usage.unit) == ("individual_pro", dt.date(2026, 12, 1), "credits")
    assert usage.premium is not None
    # what is gone from the limit (22.7), not the answer's rounded down credits_used (22)
    assert usage.premium.used == pytest.approx(22.7)
    assert (usage.premium.limit, usage.premium.unlimited) == (7000, False)
    assert usage.premium.percent_used == pytest.approx(0.4)
    assert usage.chat is not None
    assert usage.chat.unlimited
    assert len(seen) == 1  # one request, to GitHub, with the stored token
    assert str(seen[0].url) == copilot.API_URL
    assert seen[0].headers["authorization"] == f"Bearer {TOKEN}"


def test_a_seat_billed_in_requests_counts_what_is_gone_from_the_limit() -> None:
    premium = _snapshot(entitlement=300, quota_remaining=225, percent_remaining=75.0, unlimited=False)
    del premium["credits_used"]
    answer = {"copilot_plan": "business", "quota_snapshots": {"premium_interactions": premium}}
    usage = copilot.copilot_usage(_client(200, answer))
    assert (usage.plan, usage.unit, usage.resets) == ("business", "requests", None)
    assert usage.premium is not None
    assert (usage.premium.used, usage.premium.percent_used) == (75, 25)
    assert usage.chat is None  # not in the answer: left out, not guessed


def test_an_answer_without_quotas_has_no_premium() -> None:
    assert copilot.copilot_usage(_client(200, {"copilot_plan": "business"})).premium is None


@pytest.mark.parametrize("status", [401, 403, 404])
def test_a_refusal_keeps_what_github_said(status: int) -> None:
    with pytest.raises(copilot.CopilotRefusedError, match=f"{status}: Resource not accessible"):
        copilot.copilot_usage(_client(status, {"message": "Resource not accessible"}))


def test_no_stored_token_sends_nothing(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(copilot, "get_settings", lambda: SimpleNamespace(github_copilot_token=None))
    seen: list[httpx2.Request] = []
    with pytest.raises(copilot.CopilotRefusedError, match="ds settings sync"):
        copilot.copilot_usage(_client(200, ANSWER, seen))
    assert seen == []


HEADERS = {
    "x-quota-snapshot-chat": "ent=-1&ov=0.0&ovPerm=false&rem=100.0&rst=2026-12-01T00%3A00%3A00Z",
    "x-quota-snapshot-premium_interactions": "ent=7000&ov=0.0&ovPerm=false&rem=99.4&rst=2026-12-01T00%3A00%3A00Z",
}


def test_an_answers_headers_give_the_quota_with_no_request() -> None:
    usage = copilot.usage_from_headers(HEADERS)
    assert usage is not None
    assert usage.premium is not None
    assert usage.resets == dt.date(2026, 12, 1)
    assert usage.premium.limit == 7000
    assert usage.premium.percent_used == pytest.approx(0.6)
    assert usage.premium.used == pytest.approx(42)  # from the percent: exact to 7 credits
    assert usage.chat is not None
    assert usage.chat.unlimited
    assert usage.completions is None


@pytest.mark.parametrize("headers", [{}, {"x-quota-snapshot-premium_interactions": "rem=oops"}, {"x-request-id": "1"}])
def test_headers_without_a_readable_premium_quota_give_nothing(headers: dict[str, str]) -> None:
    assert copilot.usage_from_headers(headers) is None
